{% assign FlowNodes = CompositeIdeas | GetIdeasDefinedAs:'Questionnaire_Start;Questionnaire_Question;Text_Question;Long_Text_Question;Integer_Question;Decimal_Question;Single_Choice_Question;Multiple_Choice_Question;Boolean_Question;Date_Question;Calculated_Question;Questionnaire_Decision;Questionnaire_Branch_Split;Questionnaire_Branch_Merge;Questionnaire_End' -%}
{% assign FirstFlow = FlowNodes | First -%}
{% assign DataItems = CompositeIdeas | GetIdeasDefinedAs:'Questionnaire_Answer_Variable;Questionnaire_Data_Object;Questionnaire_Data_Field' -%}
<?xml version="1.0" encoding="UTF-8"?>
<scxml xmlns="{{ Questionnaire_SCXMLNamespace | DefaultIfEmpty: 'http://www.w3.org/2005/07/scxml' | EscapeXmlAttribute }}"
       version="1.0"
       name="{{ Name | DefaultIfEmpty: TechName | EscapeXmlAttribute }}"
       initial="{{ Questionnaire_InitialState | DefaultIfEmpty: FirstFlow.TechName | DefaultIfEmpty: TechName | NormalizeTechName | EscapeXmlAttribute }}">
  <datamodel>
    <data id="_questionnaire" expr="{}" />
    <data id="_questionnaire_current_prompt" expr="''" />
    <data id="_questionnaire_current_answer" expr="null" />
{%- for DataItem in DataItems %}
    <data id="{{ DataItem.Data_VariableName | DefaultIfEmpty: DataItem.TechName | NormalizeTechName | EscapeXmlAttribute }}" expr="{{ DataItem.Data_InitialValue | DefaultIfEmpty: 'null' | EscapeXmlAttribute }}" />
{%- endfor %}
  </datamodel>
{%- if FlowNodes.Any %}
{%- for Node in FlowNodes %}
{%- inject 'QuestionnaireNodeState' with Node %}
{%- endfor %}
{%- else %}
  <state id="{{ TechName | NormalizeTechName | EscapeXmlAttribute }}_start">
    <transition event="{{ Questionnaire_AnswerEvent | DefaultIfEmpty: 'answer.submit' | EscapeXmlAttribute }}" target="{{ TechName | NormalizeTechName | EscapeXmlAttribute }}_complete" />
  </state>
{%- endif %}
  <final id="{{ TechName | NormalizeTechName | EscapeXmlAttribute }}_complete" />
</scxml>

%%:SubTemplate=QuestionnaireNodeState
{% assign NodeDef = IdeaDefinitor.TechName -%}
{% if NodeDef == 'Questionnaire_End' -%}
  <final id="{{ TechName | NormalizeTechName | EscapeXmlAttribute }}" />
{% else -%}
  <state id="{{ TechName | NormalizeTechName | EscapeXmlAttribute }}">
    <onentry>
      <assign location="_questionnaire.currentState" expr="'{{ TechName | NormalizeTechName | EscapeXmlAttribute }}'" />
      <assign location="_questionnaire_current_prompt" expr="'{{ Question_Prompt | DefaultIfEmpty: Summary | DefaultIfEmpty: Name | EscapeXmlAttribute }}'" />
    </onentry>
{%- assign EmittedTransition = false -%}
{%- for Link in AssociatingLinks -%}
{%- if Link.RoleDefinitor.RoleType == 'Origin' -%}
{%- assign Rel = Link.OwnerRelationship -%}
{%- assign RelDef = Rel.RelationshipDefinitor.Value.TechName -%}
{%- if RelDef == 'Questionnaire_Next' or RelDef == 'Questionnaire_Branches_To' or RelDef == 'Questionnaire_Conditional_Branch' or RelDef == 'Questionnaire_Default_Branch' or RelDef == 'Questionnaire_Converges_To' -%}
{%- assign TargetLink = Rel.TargetLinks | First -%}
{%- assign Target = TargetLink.AssociatedIdea -%}
{%- assign EventName = Rel.Relationship_Flow_EventName | DefaultIfEmpty: 'answer.submit' -%}
{%- assign Condition = Rel.Relationship_Flow_ConditionExpression -%}
{%- if RelDef == 'Questionnaire_Conditional_Branch' and Condition.Any %}
    <transition event="{{ EventName | EscapeXmlAttribute }}" cond="{{ Condition | EscapeXmlAttribute }}" target="{{ Target.TechName | NormalizeTechName | EscapeXmlAttribute }}" />
{%- else %}
    <transition event="{{ EventName | EscapeXmlAttribute }}" target="{{ Target.TechName | NormalizeTechName | EscapeXmlAttribute }}" />
{%- endif -%}
{%- assign EmittedTransition = true -%}
{%- endif -%}
{%- endif -%}
{%- endfor -%}
{%- unless EmittedTransition %}
    <transition event="answer.submit" target="{{ OwnerContainer.TechName | DefaultIfEmpty: OwnerComposition.TechName | NormalizeTechName | EscapeXmlAttribute }}_complete" />
{%- endunless %}
  </state>
{% endif -%}

