%%:FileName={{ TechName }}.txt
********************************************************************************
Name.....: {{ Name }}
Tech-Name: {{ TechName }}
Global-Id: {{ GlobalId }}
Summary..: {{ Summary }}

{% if TechSpec != null and TechSpec != '' -%}
Tech-Spec:
{{ TechSpec }}
{% endif -%}

{% if Description != null and Description != '' -%}
Description:
{{ Description | ToUnformattedText }}
{% endif -%}

{%- comment -%}
{% if Pictogram != null -%}
Pictogram:
{{ Pictogram | ToBase64 }}
{% endif -%}
{%- endcomment -%}

{%- if Markings.Size > 0 -%}
--------------------------------------------------------------------------------
MARKINGS ({{ Markings.Size }})
{%- for Mark in Markings -%}
    * {{ Mark.Definitor.Name }} ({{ Mark.Definitor.Summary }})
    {%- if Mark.Descriptor != null -%}
        Descriptor: {{ Mark.Descriptor.Name }} -- {{ Mark.Descriptor.Summary }}
    {%- endif -%}
{%- endfor -%}
{%- endif -%}

{%- if Details.Size > 0 -%}
--------------------------------------------------------------------------------
DETAILS ({{ Details.Count }})
{%- for Detail in Details -%}
    Desigantion: {{ Detail.Designation.Name }}
    Kind.......: {{ Detail.Kind.Name }}
    
  {%- case Detail.Kind.TechName -%}
  {%- when 'Table' -%}
    Records ({{ Detail.Count }})...
    {%- for Record in Detail.Records -%}
        #{{ forloop.index }}: {%- for FieldDef in Detail.Definition.FieldDefinitions -%}'{{ FieldDef.Name }}'=[{{ Record[FieldDef.TechName] }}]; {%- endfor %}
    {%- endfor -%}

  {%- when 'Link' -%}
    Target: {{ Detail.TargetAddress }}
  {%- when 'Attachment' -%}
    Source: {{ Detail.Source }}
    {% comment -%} This can be huge for attached images
    Content: {{ Detail.Content | ToPlainText }}
    {%- endcomment -%}
  {%- endcase %}
  ................................
{%- endfor -%}
{%- endif -%}

{%- if RelatedFrom.Any or RelatingTo.Any -%}
--------------------------------------------------------------------------------
{%- if RelatedFrom.Any -%}
RELATED FROM...
{%- for Relationship in LinkedFrom -%}
    * '{{ Relationship.Name }}' ==>> {%- for Idea in Relationship.OriginIdeas -%} '{{ Idea.Name }}'; {%- endfor -%}.
{%- endfor -%}
{%- endif -%}

{%- if RelatingTo.Any -%}
RELATING TO...
{%- for Relationship in LinkingTo -%}
    * '{{ Relationship.Name }}' ==>> {%- for Idea in Relationship.TargetIdeas -%} '{{ Idea.Name }}'; {%- endfor -%}.
{%- endfor -%}
{%- endif -%}
{%- endif -%}

%%:FileName={{ TechName }}.xml
<?xml version="1.0" encoding="utf-16"?>
<{{ SelfKind.TechName }}>
    <GlobalId>{{ GlobalId }}</GlobalId>
    <Name>{{ Name | Escape }}</Name>
    <TechName>{{ TechName }}</TechName>
    <Summary>
        {{ Summary | Escape }}
    </Summary>
    <TechSpec>
        {{ TechSpec | Escape }}
    </TechSpec>
    <Description>
        {{ Description | ToUnformattedText | Escape }}
    </Description>
    <Pictogram>
        {{ Pictogram | ToBase64 }}
    </Pictogram>

    {%- if Markings.Size > 0 -%}
    <Markings Count="{{ Markings.Size }}">
    {%- for Mark in Markings -%}
        <Mark>
            <DefinitorName>{{ Mark.Definitor.Name }}</DefinitorName>
            <DefinitorSummary>{{ Mark.Definitor.Summary }}</DefinitorSummary>
            {%- if Mark.Descriptor != null -%}
            <DescriptorName>{{ Mark.Descriptor.Name }}</DescriptorName>
            <DescriptorSummary>{{ Mark.Descriptor.Summary }}</DescriptorSummary>
            {%- endif -%}
        </Mark>
    {%- endfor -%}
    </Markings>
    {%- endif -%}

    {%- if Details.Size > 0 -%}
    <Details Count="{{ Details.Size }}">
    {%- for Detail in Details -%}
        <{{ Detail.Kind.TechName }}>
            <Designation>{{ Detail.Designation.Name }}</Designation>
            {%- case Detail.Kind.TechName -%}
            {%- when 'Table' -%}
            <Records Count="{{ Detail.Records.Size }}">
            {%- for Record in Detail.Records -%}
                <Record Index="{{ forloop.index }}">{%- for FieldDef in Detail.Definition.FieldDefinitions -%}<Field Name="{{ FieldDef.Name }}">{{ Record[FieldDef.TechName] }}</Field>{%- endfor %}</Record>
            {%- endfor -%}
            </Records>
            {%- when 'Link' -%}
            <Target>{{ Detail.TargetAddress }}</Target>
            {%- when 'Attachment' -%}
            <Source>{{ Detail.Source }}</Source>
            {% comment %} This can be huge for attached images {% endcomment -%}
            <Content>{%- if Detail.Content.Size <= 1000 -%}{{ Detail.Content | ToPlainText }}{%- else -%}[EXCESIVE SIZE: {{ Detail.Content.Size }} BYTES]{%- endif -%}</Content>
            {%- endcase %}
        </{{ Detail.Kind.TechName }}>
    {%- endfor -%}
    </Details>
    {%- endif -%}

    {%- if LinkedFrom.Any -%}
    <LinkedFrom Count="{{ LinkedFrom.Size }}">
    {%- for Relationship in LinkedFrom -%}
        <Origin>
            <Relationship>{{ Relationship.Name }}</Relationship>
            <OriginIdeas>{%- for Idea in Relationship.OriginIdeas -%}<Idea>{{ Idea.Name }}</Idea>{%- endfor -%}</OriginIdeas>
        </Origin>
    {%- endfor -%}
    </LinkedFrom>
    {%- endif -%}

    {%- if LinkingTo.Any -%}
    <LinkingTo Count="{{ LinkingTo.Size }}">
    {%- for Relationship in LinkingTo -%}
        <Target>
            <Relationship>{{ Relationship.Name }}</Relationship>
            <TargetIdeas>{%- for Idea in Relationship.TargetIdeas -%}<Idea>{{ Idea.Name }}</Idea>{%- endfor -%}</TargetIdeas>
        </Target>
    {%- endfor -%}
    </LinkingTo>
    {%- endif -%}



</{{ SelfKind.TechName }}>

